// unsoftbank: the text with SoftBank emoji as standard emoji (unchanged, and not copied, without any).
func unsoftbank(s string) string {
	found := false
	for _, r := range s {
		if r >= 0xE001 && r <= 0xE537 {
			found = true
			break
		}
	}
	if !found {
		return s
	}
	var b []rune
	for _, r := range s {
		if e, ok := softbank[r]; ok {
			b = append(b, []rune(e)...)
		} else {
			b = append(b, r)
		}
	}
	return string(b)
}

// softbankWriter: everything the core hands the UI goes out with standard emoji (the JSON encoder
// writes each value in one Write; the replaced runes are never quotes or escapes).
type softbankWriter struct{ w io.Writer }

func (s softbankWriter) Write(p []byte) (int, error) {
	if _, err := s.w.Write([]byte(unsoftbank(string(p)))); err != nil {
		return 0, err
	}
	return len(p), nil
}
